// src/lib/actions/goals.ts
'use server';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { requireAuth } from './_auth';

export async function getGoals() {
  const user = await requireAuth();
  const goals = await prisma.goal.findMany({
    where: { userId: user.id },
    include: {
      transfers: { select: { baseAmountMinor: true } },
    },
    orderBy: { deadline: 'asc' },
  });

  return goals.map(g => {
    const currentAmountMinor = g.transfers.reduce((sum, t) => sum + t.baseAmountMinor, 0);
    const { transfers, ...rest } = g;
    return { ...rest, currentAmountMinor };
  });
}

/* ── Add (Zod-validated) ──────────────────────────────────── */
export async function addGoal(raw: {
  name: string; category: string; targetAmountMinor: number;
  deadline?: string;
}) {
  const { AddGoalSchema } = await import('@/lib/validation');
  const data = AddGoalSchema.parse(raw);
  const user = await requireAuth();
  await prisma.goal.create({
    data: {
      name:          data.name,
      category:      data.category,
      targetAmountMinor:  data.targetAmountMinor,
      deadline:      data.deadline ? new Date(data.deadline) : null,
      userId:        user.id,
    },
  });
  revalidatePath('/goals');
  revalidatePath('/');
}

export async function deleteGoal(id: string) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');
  await prisma.goal.deleteMany({ where: { id, userId: user.id } });
  revalidatePath('/goals');
  revalidatePath('/');
}

export async function editGoal(id: string, data: {
  name?: string; category?: string; targetAmountMinor?: number; deadline?: string | null;
}) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');

  const updateData: any = { ...data };
  if (data.deadline !== undefined) {
    updateData.deadline = data.deadline ? new Date(data.deadline) : null;
  }

  const { count } = await prisma.goal.updateMany({
    where: { id, userId: user.id },
    data: updateData,
  });
  if (count === 0) throw new Error('Goal not found or ownership failed');
  
  revalidatePath('/goals');
  revalidatePath('/');
}

// src/lib/actions/loans.ts
'use server';
import { prisma } from '@/lib/prisma';
import { revalidatePath } from 'next/cache';
import { requireAuth } from './_auth';
import { computeLoanBalance } from '@/lib/shared-computations';

export async function getLoansForUser(userId: string) {
  const today = new Date();

  const loans = await prisma.loan.findMany({
    where:   { userId: userId },
    include: {
      transfers: { select: { baseAmountMinor: true } }
    },
    orderBy: { annualRate: 'desc' },
  });

  return loans.map(l => {
    const due  = new Date(l.nextDue);
    const auto = due < today
      ? Math.floor((today.getTime() - due.getTime()) / 86_400_000)
      : 0;
    const repaidAmount = l.transfers.reduce((s, t) => s + t.baseAmountMinor, 0);
    const currentBalanceMinor = computeLoanBalance(l.balanceMinor, repaidAmount);
    
    const { transfers, ...rest } = l;
    return { ...rest, balanceMinor: currentBalanceMinor, daysOverdue: auto };
  });
}

export async function getLoans() {
  const user = await requireAuth();
  return getLoansForUser(user.id);
}

/* ── Add (Zod-validated) ──────────────────────────────────── */
export async function addLoan(raw: {
  name: string; lender: string; type: string;
  originalAmountMinor: number; balanceMinor: number;
  annualRate: number; monthlyPaymentMinor: number; nextDue: string;
}) {
  const { AddLoanSchema } = await import('@/lib/validation');
  const data = AddLoanSchema.parse(raw);
  const user = await requireAuth();
  await prisma.loan.create({
    data: {
      ...data,
      userId: user.id,
      nextDue: new Date(data.nextDue),
      originalAmountMinor: data.originalAmountMinor,
      balanceMinor: data.balanceMinor,
      monthlyPaymentMinor: data.monthlyPaymentMinor,
    },
  });
  revalidatePath('/loans');
  revalidatePath('/');
}

export async function deleteLoan(id: string) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');
  await prisma.loan.deleteMany({ where: { id, userId: user.id } });
  revalidatePath('/loans');
  revalidatePath('/');
}

export async function editLoan(id: string, data: {
  name?: string; lender?: string; type?: string; originalAmountMinor?: number; balanceMinor?: number;
  annualRate?: number; monthlyPaymentMinor?: number; nextDue?: string;
}) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');

  const updateData: any = { ...data };
  if (data.nextDue) updateData.nextDue = new Date(data.nextDue);

  const { count } = await prisma.loan.updateMany({
    where: { id, userId: user.id },
    data: updateData,
  });
  if (count === 0) throw new Error('Loan not found or ownership failed');
  
  revalidatePath('/loans');
  revalidatePath('/');
}

// src/lib/actions/transactions.ts
'use server';
import { prisma } from '@/lib/prisma';
import { periodDates } from '@/lib/dateUtils';
import { revalidatePath } from 'next/cache';
import { requireAuth } from './_auth';
import { getAccountBalances } from './accounts';

/* ── List ─────────────────────────────────────────────────── */
export async function getTransactions(period = 'this-month', type?: string) {
  const user = await requireAuth();
  const { from, to } = periodDates(period);

  return prisma.transaction.findMany({
    where: {
      userId: user.id,
      date: { gte: from, lte: to },
      ...(type && type !== 'all' ? { type } : {}),
    },
    include: { category: true },
    orderBy: { date: 'desc' },
  });
}

/* ── Summary for period ───────────────────────────────────── */
export async function getTransactionSummary(period = 'this-month') {
  const user = await requireAuth();
  const { from, to } = periodDates(period);

  const prevFrom = new Date(from); prevFrom.setMonth(prevFrom.getMonth() - 1);
  const prevTo = new Date(to); prevTo.setMonth(prevTo.getMonth() - 1);

  const income   = await prisma.transaction.aggregate({ where: { userId: user.id, type: 'income',   date: { gte: from, lte: to } }, _sum: { baseAmountMinor: true } });
  const expenses = await prisma.transaction.aggregate({ where: { userId: user.id, type: 'expense',  date: { gte: from, lte: to } }, _sum: { baseAmountMinor: true } });
  const prevInc  = await prisma.transaction.aggregate({ where: { userId: user.id, type: 'income',   date: { gte: prevFrom, lte: prevTo } }, _sum: { baseAmountMinor: true } });
  const prevExp  = await prisma.transaction.aggregate({ where: { userId: user.id, type: 'expense',  date: { gte: prevFrom, lte: prevTo } }, _sum: { baseAmountMinor: true } });

  const inc = income._sum.baseAmountMinor ?? 0;
  const exp = expenses._sum.baseAmountMinor ?? 0;

  const transfersOut = await prisma.transfer.aggregate({
    where: { userId: user.id, toAccountId: null, date: { gte: from, lte: to } },
    _sum: { baseAmountMinor: true }
  });
  const moneyOut = exp + (transfersOut._sum.baseAmountMinor ?? 0);

  return {
    income:     inc,
    expenses:   exp,
    moneyOut:   moneyOut,
    savings:    inc - exp,
    savingRate: inc > 0 ? Math.round(((inc - exp) / inc) * 100) : 0,
  };
}

/* ── Monthly chart data (last 6 months) — single query ────── */
export async function getMonthlyChartData() {
  const user  = await requireAuth();
  const now   = new Date();
  const start = new Date(now.getFullYear(), now.getMonth() - 5, 1);
  const end   = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);

  type Row = { yr: number; mo: number; type: string; total: number };
  const rows: Row[] = await prisma.$queryRaw`
    SELECT
      EXTRACT(YEAR  FROM date)::int  AS yr,
      EXTRACT(MONTH FROM date)::int  AS mo,
      type,
      SUM("baseAmountMinor")::float  AS total
    FROM "Transaction"
    WHERE
      "userId" = ${user.id}
      AND type IN ('income','expense')
      AND date >= ${start}
      AND date <= ${end}
    GROUP BY yr, mo, type
    ORDER BY yr, mo
  `;

  const months: { label: string; yr: number; mo: number }[] = [];
  for (let i = 5; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    months.push({ label: d.toLocaleString('default', { month: 'short' }), yr: d.getFullYear(), mo: d.getMonth() + 1 });
  }

  return months.map(m => {
    const inc = rows.find(r => r.yr === m.yr && r.mo === m.mo && r.type === 'income');
    const exp = rows.find(r => r.yr === m.yr && r.mo === m.mo && r.type === 'expense');
    return { month: m.label, income: Math.round(inc?.total ?? 0), expenses: Math.round(exp?.total ?? 0) };
  });
}

/* ── Category breakdown ───────────────────────────────────── */
export async function getCategoryBreakdown(period = 'this-month') {
  const user = await requireAuth();
  const { from, to } = periodDates(period);

  const rows = await prisma.transaction.groupBy({
    by: ['categoryId'],
    where: { userId: user.id, type: 'expense', date: { gte: from, lte: to } },
    _sum: { baseAmountMinor: true },
    orderBy: { _sum: { baseAmountMinor: 'desc' } },
  });

  const categories = await prisma.category.findMany({
    where: { id: { in: rows.map(r => r.categoryId) } },
  });
  const catMap = Object.fromEntries(categories.map(c => [c.id, c]));

  const total = rows.reduce((s, r) => s + (r._sum.baseAmountMinor ?? 0), 0);
  return rows.map(r => ({
    name:  catMap[r.categoryId]?.name ?? r.categoryId,
    icon:  catMap[r.categoryId]?.icon ?? 'other',
    value: r._sum.baseAmountMinor ?? 0,
    pct:   total > 0 ? Math.round(((r._sum.baseAmountMinor ?? 0) / total) * 100) : 0,
  }));
}

/* ── Categories list ──────────────────────────────────────── */
export async function getCategories(type?: 'income' | 'expense' | 'savings') {
  const user = await requireAuth();
  return prisma.category.findMany({
    where: {
      userId: user.id,
      ...(type ? { type } : {}),
    },
    orderBy: { name: 'asc' },
  });
}

/* ── Add (Zod-validated) ──────────────────────────────────── */
export async function addTransaction(raw: {
  name: string; baseAmountMinor: number; type: string;
  categoryId: string; accountId?: string; date: string; note?: string;
}) {
  const { AddTransactionSchema } = await import('@/lib/validation');
  const data = AddTransactionSchema.parse(raw);
  const user = await requireAuth();

  // RLS-equivalent: validate category belongs to this user
  const cat = await prisma.category.findFirst({
    where: { id: data.categoryId, userId: user.id },
  });
  if (!cat) throw new Error('Please choose a valid category.');

  // Find a default account if not provided
  let accountId = data.accountId;
  if (!accountId) {
    const firstAccount = await prisma.account.findFirst({ where: { userId: user.id }, orderBy: { createdAt: 'asc' }});
    if (firstAccount) accountId = firstAccount.id;
    else {
      const fallback = await prisma.account.create({ data: { userId: user.id, name: 'Default Account', type: 'bank', currency: 'KES' }});
      accountId = fallback.id;
    }
  }

  // Overdraft prevention
  if (data.type === 'expense' && accountId) {
    const { toMajor } = await import('@/lib/money');
    const balances = await getAccountBalances(user.id);
    const acc = balances.find(a => a.id === accountId);
    if (acc && acc.type !== 'credit_card' && acc.balanceMinor - data.baseAmountMinor < 0) {
      throw new Error(`Not enough money in ${acc.name}. Available: ${acc.currency} ${toMajor(acc.balanceMinor)}.`);
    }
  }

  const newTx = await prisma.transaction.create({
    data: { 
      name: data.name,
      baseAmountMinor: data.baseAmountMinor,
      type: data.type === 'income' ? 'income' : 'expense',
      categoryId: data.categoryId,
      accountId: accountId,
      note: data.note,
      date: new Date(data.date), 
      userId: user.id 
    },
  });

  // Security Audit
  const { logActivity } = await import('@/lib/audit');
  await logActivity({
    userId: user.id,
    action: 'CREATE',
    resource: 'Transaction',
    metadata: { txId: newTx.id, amount: data.baseAmountMinor, name: data.name },
  });
  revalidatePath('/transactions');
  revalidatePath('/');
}

/* ── Bulk import (Smart Upload) ───────────────────────────── */
export async function importTransactions(rows: {
  name: string; baseAmountMinor: number; type: string;
  categoryName: string; date: string; note?: string;
  reference?: string; importHash?: string;
}[], targetAccountId: string) {
  const user = await requireAuth();
  if (!Array.isArray(rows) || rows.length === 0) throw new Error('No rows to import');
  if (rows.length > 500) throw new Error('Max 500 rows per import');
  if (!targetAccountId) throw new Error('Account ID is required for import');

  // Verify the target account exists and belongs to the user
  const account = await prisma.account.findFirst({ where: { id: targetAccountId, userId: user.id } });
  if (!account) throw new Error('Selected account not found');

  // Resolve or create categories dynamically based on the string provided by the user
  const categoryNames = [...new Set(rows.map(r => String(r.categoryName)))];
  const existingCats  = await prisma.category.findMany({ where: { userId: user.id, name: { in: categoryNames } } });
  const catMap: Record<string, string> = Object.fromEntries(existingCats.map(c => [c.name, c.id]));

  for (const name of categoryNames) {
    if (!catMap[name]) {
      const typeHint = rows.find(r => r.categoryName === name)?.type === 'income' ? 'income' : 'expense';
      const cat = await prisma.category.create({
        data: { name, type: typeHint, userId: user.id },
      });
      catMap[name] = cat.id;
    }
  }

  await prisma.transaction.createMany({
    data: rows
      .filter(r => {
        // Drop anything that isn't strictly income or expense (e.g. transfers)
        if (r.type !== 'income' && r.type !== 'expense') {
          console.warn('[importTransactions] Dropping non-income/expense row:', r.name, r.type);
          return false;
        }
        // Validate date before new Date() — NaN dates crash Prisma
        const d = new Date(r.date);
        if (isNaN(d.getTime())) {
          console.warn('[importTransactions] Skipping row with invalid date:', r.date, r.name);
          return false;
        }
        return true;
      })
      .map(r => ({
        name:       String(r.name).slice(0, 120),
        baseAmountMinor: Math.abs(Number(r.baseAmountMinor)),
        type:       r.type as 'income' | 'expense',
        categoryId: catMap[String(r.categoryName)],
        accountId:  targetAccountId,
        date:       new Date(r.date),
        note:       r.note ? String(r.note).slice(0, 500) : undefined,
        userId:     user.id,
        importedAt: new Date(),
        importHash: r.importHash || null,
        reference:  r.reference || null,
      })),
    // Deduplication is enforced via UI previews and importHash checks, not DB constraints
  });

  // Security Audit
  const { logActivity } = await import('@/lib/audit');
  await logActivity({
    userId: user.id,
    action: 'IMPORT',
    resource: 'Transactions',
    metadata: { rowCount: rows.length },
  });

  revalidatePath('/transactions');
  revalidatePath('/');
}

/* ── Delete (atomic — no TOCTOU race) ────────────────────── */
export async function deleteTransaction(id: string) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');

  // findFirst + delete is a TOCTOU race: another request could delete between the two calls.
  // deleteMany with userId scope is atomic AND enforces ownership in one query.
  const { count } = await prisma.transaction.deleteMany({
    where: { id, userId: user.id },
  });
  if (count === 0) throw new Error('Transaction not found or already deleted');

  // Security Audit
  const { logActivity } = await import('@/lib/audit');
  await logActivity({
    userId:   user.id,
    action:   'DELETE',
    resource: 'Transaction',
    metadata: { txId: id },
  });

  revalidatePath('/transactions');
  revalidatePath('/');
}

/* ── Edit (atomic ownership check) ────────────────────────── */
export async function editTransaction(id: string, data: {
  baseAmountMinor?: number; name?: string; type?: 'income' | 'expense'; date?: Date; categoryId?: string; accountId?: string; note?: string;
}) {
  const user = await requireAuth();
  if (!id) throw new Error('Missing id');

  const oldTx = await prisma.transaction.findFirst({ where: { id, userId: user.id } });
  if (!oldTx) throw new Error('Transaction not found');

  const newType = data.type ?? oldTx.type;
  const newAmount = data.baseAmountMinor ?? oldTx.baseAmountMinor;
  const newAccountId = data.accountId ?? oldTx.accountId;

  if (newType === 'expense' && newAccountId) {
    const { toMajor } = await import('@/lib/money');
    const balances = await getAccountBalances(user.id);
    const acc = balances.find(a => a.id === newAccountId);
    
    if (acc && acc.type !== 'credit_card') {
      let effectiveBalance = acc.balanceMinor;
      if (oldTx.type === 'expense' && oldTx.accountId === newAccountId) {
        effectiveBalance += oldTx.baseAmountMinor; // restore old amount
      } else if (oldTx.type === 'income' && oldTx.accountId === newAccountId) {
        effectiveBalance -= oldTx.baseAmountMinor; // remove old income
      }
      
      if (effectiveBalance - newAmount < 0) {
        throw new Error(`Not enough money in ${acc.name}. Available: ${acc.currency} ${toMajor(effectiveBalance)}.`);
      }
    }
  }

  const { count } = await prisma.transaction.updateMany({
    where: { id, userId: user.id },
    data,
  });
  if (count === 0) throw new Error('Transaction not found or ownership failed');

  const { logActivity } = await import('@/lib/audit');
  await logActivity({
    userId:   user.id,
    action:   'UPDATE',
    resource: 'Transaction',
    metadata: { txId: id, fields: Object.keys(data) },
  });

  revalidatePath('/transactions');
  revalidatePath('/');
}

// src/lib/behavioral.ts
import { prisma } from '@/lib/prisma';
import { getLoansForUser } from './actions/loans';

export async function safeToSpend(userId: string, period: 'weekly' | 'monthly' | 'yearly' = 'monthly'): Promise<{
  discretionaryMinor: number;
  remainingMinor: number;
  perDayMinor: number;
  daysLeft: number;
  breakdown: {
    expectedIncome: number;
    baseEnvelopeLimits: number;
    plannedSavings: number;
    loanDue: number;
    unbudgetedSpendThisPeriod: number;
    envelopeOverspendPenalty: number;
  };
}> {
  // 1. Establish period bounds
  const now = new Date();
  let from: Date, to: Date;
  
  if (period === 'monthly') {
    from = new Date(now.getFullYear(), now.getMonth(), 1);
    to = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
  } else if (period === 'weekly') {
    // Assuming Monday start
    const day = now.getDay() || 7; 
    from = new Date(now);
    from.setHours(0, 0, 0, 0);
    from.setDate(now.getDate() - day + 1);
    to = new Date(from);
    to.setDate(from.getDate() + 6);
    to.setHours(23, 59, 59, 999);
  } else {
    // yearly
    from = new Date(now.getFullYear(), 0, 1);
    to = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
  }

  const daysLeftInPeriod = Math.max(1, Math.ceil((to.getTime() - now.getTime()) / 86400000));

  // 2. Fetch User Preferences
  const prefs = await prisma.userPreferences.findUnique({ where: { userId } });
  const savingRate = prefs?.savingRate ?? 30;

  // 3. Expected Income
  let expectedIncome = 0;
  if (period === 'monthly') {
    if (prefs?.expectedMonthlyIncomeMinor != null) {
      expectedIncome = prefs.expectedMonthlyIncomeMinor;
    } else {
      // Average of income over 3 complete calendar months before current month
      const threeMonthsAgoStart = new Date(from.getFullYear(), from.getMonth() - 3, 1);
      const lastMonthEnd = new Date(from.getFullYear(), from.getMonth(), 0, 23, 59, 59, 999);
      
      const oldestIncome = await prisma.transaction.findFirst({
        where: { userId, type: 'income', date: { lte: lastMonthEnd } },
        orderBy: { date: 'asc' }
      });

      if (oldestIncome) {
        const trailingIncome = await prisma.transaction.aggregate({
          where: { userId, type: 'income', date: { gte: threeMonthsAgoStart, lte: lastMonthEnd } },
          _sum: { baseAmountMinor: true }
        });
        
        // Calculate months of history (capped at 3)
        const oldestMonth = oldestIncome.date.getFullYear() * 12 + oldestIncome.date.getMonth();
        const lastMonth = lastMonthEnd.getFullYear() * 12 + lastMonthEnd.getMonth();
        const historyMonths = Math.max(1, lastMonth - oldestMonth + 1);
        const divisor = Math.min(3, historyMonths);
        
        expectedIncome = Math.round((trailingIncome._sum.baseAmountMinor ?? 0) / divisor);
      }

      // If no history (or average is 0), fall back to current period actual income
      if (expectedIncome === 0) {
        const currentIncomeRows = await prisma.transaction.aggregate({
          where: { userId, type: 'income', date: { gte: from, lte: to } },
          _sum: { baseAmountMinor: true }
        });
        expectedIncome = currentIncomeRows._sum.baseAmountMinor ?? 0;
      }
    }
  } else {
    // Actual income recorded this period (fallback for weekly/yearly)
    const incomeRows = await prisma.transaction.aggregate({
      where: { userId, type: 'income', date: { gte: from, lte: to } },
      _sum: { baseAmountMinor: true }
    });
    expectedIncome = incomeRows._sum.baseAmountMinor ?? 0;
  }

  // 4. Planned Savings
  const plannedSavings = Math.floor(expectedIncome * (savingRate / 100));

  // 5. Loan Due
  const loans = await getLoansForUser(userId);
  let loanDue = 0;
  for (const l of loans) {
    if (l.nextDue >= from && l.nextDue <= to) {
      loanDue += l.monthlyPaymentMinor;
    }
  }

  // 6. Envelopes (Budgets)
  const budgets = await prisma.budget.findMany({
    where: { userId, period },
  });
  
  const budgetedCategoryIds = new Set(budgets.map(b => b.categoryId));
  
  let baseEnvelopeLimits = 0;
  let envelopeOverspendPenalty = 0;

  // We need to fetch spending per budget category
  for (const b of budgets) {
    baseEnvelopeLimits += b.limitAmountMinor;
    
    // Spend this period
    const spendThisPeriodAgg = await prisma.transaction.aggregate({
      where: { userId, categoryId: b.categoryId, type: 'expense', date: { gte: from, lte: to } },
      _sum: { baseAmountMinor: true }
    });
    const envelopeSpend = spendThisPeriodAgg._sum.baseAmountMinor ?? 0;
    
    let envelopeEffectiveLimit = b.limitAmountMinor;

    if (b.rollover) {
      // For rollover=true, cumulative limit - cumulative spend since the budget was created
      // Note: we assume the budget limits were the same historically. To be perfectly accurate, 
      // we sum historical periods. But since we don't have historical budget limits stored, 
      // we approximate cumulative limit by: limit * (months since budget createdAt)
      // Wait, let's look at the exact budget creation date to find how many periods existed.
      let periodsExisted = 1;
      if (b.createdAt < from) {
        if (period === 'monthly') {
          const m1 = b.createdAt.getFullYear() * 12 + b.createdAt.getMonth();
          const m2 = from.getFullYear() * 12 + from.getMonth();
          periodsExisted = Math.max(1, m2 - m1 + 1);
        } else if (period === 'yearly') {
          periodsExisted = Math.max(1, from.getFullYear() - b.createdAt.getFullYear() + 1);
        } else if (period === 'weekly') {
          periodsExisted = Math.max(1, Math.floor((from.getTime() - b.createdAt.getTime()) / (7 * 86400000)) + 1);
        }
      }
      
      const cumulativeLimit = b.limitAmountMinor * periodsExisted;
      
      // Cumulative spend (from createdAt to this period's end)
      const cumulativeSpendAgg = await prisma.transaction.aggregate({
        where: { userId, categoryId: b.categoryId, type: 'expense', date: { gte: b.createdAt, lte: to } },
        _sum: { baseAmountMinor: true }
      });
      const cumulativeSpend = cumulativeSpendAgg._sum.baseAmountMinor ?? 0;
      
      // Overspend is max(0, cumulativeSpend - cumulativeLimit)
      envelopeOverspendPenalty += Math.max(0, cumulativeSpend - cumulativeLimit);
    } else {
      // Overspend is just this period
      envelopeOverspendPenalty += Math.max(0, envelopeSpend - envelopeEffectiveLimit);
    }
  }

  // 7. Unbudgeted Spend
  const unbudgetedAgg = await prisma.transaction.aggregate({
    where: { 
      userId, 
      type: 'expense', 
      date: { gte: from, lte: to },
      categoryId: { notIn: Array.from(budgetedCategoryIds) } 
    },
    _sum: { baseAmountMinor: true }
  });
  const unbudgetedSpendThisPeriod = unbudgetedAgg._sum.baseAmountMinor ?? 0;

  // 8. Final Math
  const discretionaryMinor = expectedIncome - baseEnvelopeLimits - plannedSavings - loanDue;
  const remainingMinor = discretionaryMinor - unbudgetedSpendThisPeriod - envelopeOverspendPenalty;
  const perDayMinor = Math.floor(Math.max(0, remainingMinor) / daysLeftInPeriod);

  return {
    discretionaryMinor,
    remainingMinor,
    perDayMinor,
    daysLeft: daysLeftInPeriod,
    breakdown: {
      expectedIncome,
      baseEnvelopeLimits,
      plannedSavings,
      loanDue,
      unbudgetedSpendThisPeriod,
      envelopeOverspendPenalty
    }
  };
}
